create or alter procedure [dbo].[GetReferenceItemValues]   
 @listid int,  
 @resourceID int = 0,  
 @useApiName bit = 0,
 @applySortOrder int = 1
AS  
BEGIN  
 SET NOCOUNT ON;  

 declare	@isAdmin bit = 0,
			@listAssetTypeId int;  
 select		@listAssetTypeId = ID from AssetType where Object = 'ReferenceItemType' and ObjectID = @listid 

 select top 1  
		@isAdmin = [IsAdministrator]  
 from	[reporting].[Global_Resource]  
 where	[ResourceID] = @resourceID;  

 drop table if exists #fieldtypes  
 drop table if exists #parentTypes  
 create table #fieldtypes (identifier [int] IDENTITY(0,1) NOT NULL, ID int, Name nvarchar(250), SortOrder int, SortByAscending bit, type varchar(25))   
 create table #parentTypes (IntersectTypeID int, Name nvarchar(250), ReferenceListTypeID int, ParentLevel int)  


  if @useApiName = 1  
  begin  
   insert into #fieldtypes  
    select ID, [Name], case when SortOrder>0 then SortOrder else null end, SortByAscending, Type from fieldtype where AssetTypeID = @listAssetTypeId order by ColumnOrder  
  end  
 else  
  begin  
   insert into #fieldtypes  
    select ID, 'Field' + cast(id as varchar(100)) as [Name], case when SortOrder>0 then SortOrder else null end, SortByAscending, Type from fieldtype where AssetTypeID = @listAssetTypeId order by ColumnOrder  
  end  

 declare @parentLevel int = 0;  
 declare @currentId int = @listAssetTypeId;   

 while exists (select 1 from intersecttypedetail where ObjectAssetTypeID = @currentId and predicatetype = 3 and @parentLevel < 20)  
 begin  
	declare @_id int,
			@_subjectName nvarchar(250),
			@_subjectAssetTypeID int

	select	@_id = ID, 
			@_subjectName = SubjectName, 
			@_subjectAssetTypeID = SubjectAssetTypeID
	from	intersecttypedetail 
	where	ObjectAssetTypeID = @currentId 
			and predicatetype = 3;  

	insert into #parentTypes  values (@_id, @_subjectName, @_subjectAssetTypeID, @parentLevel);

	select @currentId = @_subjectAssetTypeID;  

	set @parentLevel = @parentLevel +1;  
 end  

 declare @tsqlSelect nvarchar(max);  
 declare @tsqlFrom nvarchar(max);  
 declare @tsqlWhere nvarchar(max);  
 declare @tsql nvarchar(max);  
 declare @tsqlSort nvarchar(max) = '';

 set @tsqlSelect = 'select O.ObjectID as [ID] , O.code as [Code], o.id as [AssetID], o.uid as [UID]';  
 set @tsqlFrom = 'from AssetType AT inner join Asset O on O.AssetTypeID = AT.ID ';  
 set @tsqlWhere = ' where AT.ID  = ' + cast(@listAssetTypeId as nvarchar(20));  
 if @resourceID > 0  
 begin  
  set @tsqlWhere = @tsqlWhere + ' and O.ID not in (select AssetID from ResponsibilityDetail where PermissionsBitMask & 1 = 0 and ResourceID = ' +  cast(@resourceID as varchar) + ') ';  
  set @tsqlWhere = @tsqlWhere + ' and O.AssetTypeID not in (select AssetTypeID from ResponsibilityDetail where AssetID = 0 and PermissionsBitMask & 1 = 0 and ResourceID = ' +  cast(@resourceID as varchar) + ') ';  
 end   

 DECLARE @name nvarchar(250);  
 DECLARE @id int = 0;  
 DECLARE @intersectTypeId int;  
 DECLARE @parentName nvarchar(250);  
 DECLARE @parentListTypeID int = 0;   
 DECLARE @index int = 0;  
 DECLARE @previousRelation varchar(200) = 'O.ID';  


 DECLARE relCur CURSOR FOR SELECT IntersectTypeId, Name, ReferenceListTypeID, ParentLevel FROM #parentTypes  
 OPEN relCur  

 FETCH NEXT FROM relCur INTO @intersectTypeId, @parentName, @parentListTypeID, @parentLevel  

 WHILE @@FETCH_STATUS = 0 BEGIN  

  SET @tsqlSelect = @tsqlSelect + ', REL_' + cast(@index as nvarchar(10)) + '.DisplayValue as [Rel' + cast(@parentListTypeID as varchar(20)) + ']';  
        SET @tsqlFrom = @tsqlFrom +' outer apply (  
        select	ID.DisplayValue, I.SubjectAssetID                              
        from	[PredicateIntersect] I  
                inner join Asset IA on I.ObjectAssetID = ' + @previousRelation + ' and IA.ID = I.SubjectAssetID and I.PredicateType = 3  
                inner join AssetType IAT on IAT.ID = IA.AssetTypeID  
				inner join AssetDisplayValue ID on ID.AssetID = IA.ID
        ) REL_' + cast(@index as nvarchar(10));  

  set @previousRelation = 'REL_' + cast(@index as nvarchar(10)) + '.SubjectAssetID';  
  SET @index = @index + 1;  
  FETCH NEXT FROM relCur INTO @intersectTypeId, @parentName, @parentListTypeID, @parentLevel  
 END  

 CLOSE relCur      
 DEALLOCATE relCur  

 set @index = 0;  

 DECLARE cur CURSOR FOR SELECT id, name FROM #fieldtypes  
 OPEN cur  

 FETCH NEXT FROM cur INTO @id, @name  

 WHILE @@FETCH_STATUS = 0 BEGIN      
  SET @tsqlSelect = @tsqlSelect + ', f'+ cast(@index as nvarchar(10)) + '.FormattedValue as [' + @name + ']';  
  SET @tsqlFrom = @tsqlFrom + ' left join [Field] f' + cast(@index as nvarchar(10)) + ' on (O.ID = f' + cast(@index as nvarchar(10)) + '.AssetID and f' + cast(@index as nvarchar(10)) + '.fieldtypeid = ' + cast(@id as nvarchar(20)) + ')';  
  SET @index = @index + 1;  
  FETCH NEXT FROM cur INTO @id, @name  
 END  

 CLOSE cur      
 DEALLOCATE cur  

 if @isAdmin = 0  
 begin  
  SET @tsqlSelect = @tsqlSelect + ', IIF(S_E.AssetID is null, 0, 1) as P_CanEdit, IIF(S_D.AssetID is null, 0, 1) as P_CanDelete '  
  set @tsqlFrom = @tsqlFrom + '  
outer apply (select top 1 AssetID from ResponsibilityDetail where AssetID = O.ID and ResourceID = ' + cast(@resourceID as varchar) + ' and (PermissionsBitMask & 2) = 2) S_E   
outer apply (select top 1 AssetID from ResponsibilityDetail where AssetID = O.ID and ResourceID = ' + cast(@resourceID as varchar) + ' and (PermissionsBitMask & 4) = 4) S_D'  
 end  
 else  
 begin   
  SET @tsqlSelect = @tsqlSelect + ', cast(1 as bit) as P_CanEdit, cast(1 as bit) as P_CanDelete '  
 end  

 if @applySortOrder = 1
  Begin

  set @tsqlSort =' order by '

  SELECT @tsqlSort = @tsqlSort + Stuff((Select ', ' + case when t2.Type in ('Counter', 'Decimal', 'Number') then 'CAST(' + 'f'+cast(identifier as nvarchar)+'.FormattedValue' + ' as float)' else 'f'+cast(identifier as nvarchar)+'.FormattedValue' end  + case when SortByAscending=1 then ' asc' else ' Desc' end
                   FROM #fieldtypes t2
				   where SortOrder > 0
				   order by SortOrder asc
                   FOR XML PATH(''), TYPE
            ).value('.', 'NVARCHAR(MAX)'), 1,2,'')
  end

 SET @tsql = @tsqlSelect + @tsqlFrom + @tsqlWhere + @tsqlSort;  
    print(@tsql);
 EXEC sp_executesql @tsql;
END

changeSet.rollback:

